// CopyFilters copies filters from another record variable (all filter groups)
func (t *ObjectTranslation) CopyFilters(from *ObjectTranslation) {
	t.filters = copyObjectTranslationFilters(from.filters)
	t.filterGroup = from.filterGroup
	t.otherFilters = nil
	for g, filters := range from.otherFilters {
		if t.otherFilters == nil {
			t.otherFilters = map[int]map[string]*objectTranslationFilterCondition{}
		}
		t.otherFilters[g] = copyObjectTranslationFilters(filters)
	}

	// Also copy order by fields
	if len(from.orderByFields) > 0 {
		t.orderByFields = make([]string, len(from.orderByFields))
		copy(t.orderByFields, from.orderByFields)
	} else {
		t.orderByFields = nil
	}
}

// copyObjectTranslationFilters returns a deep copy of a filter group's filters (nil for none)
func copyObjectTranslationFilters(from map[string]*objectTranslationFilterCondition) map[string]*objectTranslationFilterCondition {
	if from == nil {
		return nil
	}
	filters := make(map[string]*objectTranslationFilterCondition, len(from))
	for key, filter := range from {
		c := *filter
		filters[key] = &c
	}
	return filters
}

// GetFilters returns a string representation of current filters
// Useful for debugging and logging
func (t *ObjectTranslation) GetFilters() string {
	if len(t.filters) == 0 {
		return ""
	}

	var parts []string
	for _, filter := range t.filters {
		if filter.invalidField {
			parts = append(parts, "<invalid field>")
		} else if filter.isExpression {
			parts = append(parts, fmt.Sprintf("%s: %s", filter.fieldName, filter.filterExpr))
		} else if filter.minValue != nil && filter.maxValue != nil {
			parts = append(parts, fmt.Sprintf("%s: %v..%v", filter.fieldName, filter.minValue, filter.maxValue))
		} else if filter.minValue != nil {
			parts = append(parts, fmt.Sprintf("%s: >=%v", filter.fieldName, filter.minValue))
		} else if filter.maxValue != nil {
			parts = append(parts, fmt.Sprintf("%s: <=%v", filter.fieldName, filter.maxValue))
		}
	}

	return strings.Join(parts, ", ")
}

// ========================================
// Field Validation
// ========================================

// ValidateField validates a field and calls its OnValidate trigger
// This is equivalent to the VALIDATE function
// Usage: customer.ValidateField("Payment_terms_code", types.NewCode("30DAYS"))
func (t *ObjectTranslation) ValidateField(fieldName string, value interface{}) error {
	fieldNameLower := strings.ToLower(fieldName)

	switch fieldNameLower {
	case "object_type":
		// Set field value
		// Accept enum type directly
		if v, ok := value.(ObjectTranslationObject_type); ok {
			t.Object_type = v
			// Accept int (convert to enum)
		} else if v, ok := value.(int); ok {
			if v < 0 || v >= 6 {
				return fmt.Errorf("invalid option value %d for field object_type (valid range: 0-%d)", v, 6-1)
			}
			t.Object_type = ObjectTranslationObject_type(v)
			// Accept float64 (JSON numbers decode as float64)
		} else if v, ok := value.(float64); ok {
			intVal := int(v)
			if intVal < 0 || intVal >= 6 {
				return fmt.Errorf("invalid option value %d for field object_type (valid range: 0-%d)", intVal, 6-1)
			}
			t.Object_type = ObjectTranslationObject_type(intVal)
			// Accept string (lookup in options and convert)
		} else if v, ok := value.(string); ok {
			if v == "" {
				// Empty string defaults to first option (behavior)
				t.Object_type = 0
			} else {
				options := []string{"TableData", "Table", "Page", "Report", "Dataport", "Codeunit"}
				found := false
				for i, opt := range options {
					if opt == v {
						t.Object_type = ObjectTranslationObject_type(i)
						found = true
						break
					}
				}
				if !found {
					return fmt.Errorf("invalid option '%s' for field object_type (valid options: %v)", v, options)
				}
			}
		} else {
			return fmt.Errorf("invalid type for field object_type (expected ObjectTranslationObject_type, int, or string)")
		}
		// OnValidate trigger of the business logic (OnValidate of the field)
		for _, l := range t.registeredLogic() {
			if trg, ok := l.(ObjectTranslationOnValidate_Object_type); ok {
				if err := trg.OnValidate_Object_type(t); err != nil {
					return err
				}
			}
		}
		return nil
	case "object_id":
		// Set field value
		switch v := value.(type) {
		case int:
			t.Object_id = v
		case float64:
			t.Object_id = int(v)
		case string:
			if v == "" {
				t.Object_id = 0
			} else if i, err := strconv.Atoi(v); err == nil {
				t.Object_id = i
			} else {
				return fmt.Errorf("invalid integer value for field object_id: %s", v)
			}
		default:
			return fmt.Errorf("invalid type for field object_id")
		}
		// OnValidate trigger of the business logic (OnValidate of the field)
		for _, l := range t.registeredLogic() {
			if trg, ok := l.(ObjectTranslationOnValidate_Object_id); ok {
				if err := trg.OnValidate_Object_id(t); err != nil {
					return err
				}
			}
		}
		return nil
	case "language_id":
		// Set field value
		if v, ok := value.(types.Code); ok {
			t.Language_id = v
		} else if v, ok := value.(string); ok {
			t.Language_id = types.NewCode(v)
		} else {
			return fmt.Errorf("invalid type for field language_id")
		}
		// OnValidate trigger of the business logic (OnValidate of the field)
		for _, l := range t.registeredLogic() {
			if trg, ok := l.(ObjectTranslationOnValidate_Language_id); ok {
				if err := trg.OnValidate_Language_id(t); err != nil {
					return err
				}
			}
		}
		return nil
	case "object_name":
		// Set field value
		if v, ok := value.(types.Text); ok {
			t.Object_name = v
		} else if v, ok := value.(string); ok {
			t.Object_name = types.NewText(v)
		} else {
			return fmt.Errorf("invalid type for field object_name")
		}
		// OnValidate trigger of the business logic (OnValidate of the field)
		for _, l := range t.registeredLogic() {
			if trg, ok := l.(ObjectTranslationOnValidate_Object_name); ok {
				if err := trg.OnValidate_Object_name(t); err != nil {
					return err
				}
			}
		}
		return nil
	}

	return fmt.Errorf("field '%s' not found", fieldName)
}

